const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),lines=b=>b.toString().trim().split('\n').filter(Boolean),sort=a=>a.sort((a,b)=>a.localeCompare(b));
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyWordUseLanguageReview(read=readFileSync){
 const json=f=>JSON.parse(read(f)),r=json('docs/klink-owner-release-word-use-language-review-20261101.json');assert.equal(r.approvedBy,'Nico');assert(r.publicationApproved&&r.appearanceUnchanged);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);assert(r.userRequest.includes('Vloeiendheid, natuurlijkheid, grammatica, spelling'));assert(r.audioAuthorization.includes('audio via ElevenLabs'));git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort([...new Set([...lines(git('diff','--name-only',base,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,r.changedFiles);assert.deepEqual(sort(Object.keys(r.files)),changed);for(const f of changed)assert.equal(sha(read(f)),r.files[f],f);for(const[f,h]of Object.entries(r.evidenceFiles))assert.equal(sha(read(f)),h,f);
 assert.equal(git('diff','--name-only',base,'--','app','components','hooks','lib','db','drizzle','.github','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','package.json','package-lock.json','vite.config.ts','wrangler.jsonc').length,0,'Only lesson language, matching audio and review checks may change');
 const bank=json('data/klink-word-use.json'),old=JSON.parse(git('show',base+':data/klink-word-use.json')),review=json(folder+'content-review.json');assert.equal(bank.entries.length,288);assert.equal(review.rows.length,288);assert.equal(review.answerCardsReviewed,1152);assert.equal(review.changedRows,139);assert.equal(review.bankSha256,sha(read('data/klink-word-use.json')));assert.equal(review.editorialReview,'completed');assert.equal(review.independentHumanReview,false);assert.equal(review.individualCefrValidated,false);assert.equal(review.classroomPilot,'open');
 for(const e of bank.entries){const before=old.entries.find(x=>x.id===e.id),checked=review.rows.find(x=>x.id===e.id);assert(before&&checked);for(const k of['id','activity','level','theme','collectionId'])assert.equal(e[k],before[k]);for(const k of['context','prompt','spokenPrompt','options','answer','explanation'])assert.deepEqual(checked[k],e[k]);for(const dim of review.dimensions)assert.equal(checked[dim],true);assert(checked.allFourOptionsReviewed&&checked.uniqueCorrectAnswer);assert.equal(e.options.length,4);assert.equal(new Set(e.options).size,4);assert.equal(e.options.indexOf(e.answer),before.options.indexOf(before.answer));assert.equal(e.options.filter(x=>x===e.answer).length,1);}
 for(const a of['word-combinations','suitable-reply'])for(const l of['a1','a2','b1'])assert.equal(bank.entries.filter(e=>e.activity===a&&e.level===l).length,48);
 const spell=json(folder+'spelling-check.json');assert.equal(spell.fieldsChecked,2304);assert.equal(spell.entriesChecked,288);assert(spell.reviewCompleted);assert.deepEqual(spell.unresolved,[]);
 const plan=json(folder+'voice-plan.json'),audio=json(folder+'audio.json'),bindings=json('data/klink-word-use-audio.json'),prior=JSON.parse(git('show',base+':data/klink-word-use-audio.json'));assert.equal(plan.provider,'ElevenLabs');assert.equal(plan.instructionVoiceId,'h6uBOiAjLKklte8hdYio');assert.deepEqual(plan.targetVoiceIds,['0qLmDzgqulxcvv0yf3kg','7qdUFMklKPaaAVMsBTBt']);assert.equal(plan.model,'eleven_v4');assert.equal(audio.length,1293);assert.equal(plan.clips.length,audio.length);assert.equal(audio.filter(c=>!c.reused).length,203);for(const[k,b]of Object.entries(prior))assert.deepEqual(bindings[k],b);assert.equal(Object.keys(bindings).length,Object.keys(prior).length+203);
 for(const e of bank.entries){const u=plan.uses[e.id];assert(u);assert.equal(bindings[u.prompt].transcript,e.spokenPrompt);for(const option of e.options)assert.equal(bindings[u.options[option]].transcript,option);assert.equal(bindings[u.instruction].role,'instruction');assert(bindings[u.instruction].transcript.endsWith(e.context));}
 const previousPublic=new Set(lines(git('ls-tree','-r','--name-only',base,'--','public')));
 for(const c of audio){const b=bindings[c.role+':'+c.text];assert(b);for(const k of['src','role','voiceId'])assert.equal(b[k],c[k]);assert.equal(b.transcript,c.text);assert(b.metadataApproved&&b.review==='approved');assert.equal(c.voiceId===plan.instructionVoiceId,c.role==='instruction');assert.equal(sha(read('public'+c.src)),c.sha256);for(const k of['artist','album_artist','publisher'])assert.equal(c.metadata[k],'Taalroute');assert(!/elevenlabs|suno|openai|generator/i.test(JSON.stringify(c.metadata)));if(!c.reused){assert(c.audioPacketsUnchanged&&c.audioPacketsSha256&&c.originalSha256&&c.metadataVerified);assert.equal(c.clippedSamples,0);assert(!previousPublic.has('public'+c.src));}}
 for(const f of changed.filter(f=>f.startsWith('public/')))assert(audio.some(c=>!c.reused&&'public'+c.src===f),'Only active new audio; keep all published audio unchanged');
 const speech=json(folder+'speech-review.json');assert.equal(speech.checked,203);assert(speech.reviewCompleted&&speech.all203SpokenTextsAccountedFor);assert.deepEqual(speech.unresolved,[]);assert.equal(speech.flags.length,5);assert(speech.flags.every(f=>f.reviewCompleted));for(const c of audio.filter(c=>!c.reused)){const s=speech.checks.find(s=>s.id===c.id);assert(s);assert.equal(s.text,c.text);assert(s.normalizedMatch||speech.flags.some(f=>f.id===c.id&&f.reviewCompleted));}
 const browser=json(folder+'local/browser-checks.json'),playback=json(folder+'local/audio-browser-checks.json');assert.equal(browser.checks.length,576);assert.equal(browser.layouts.length,72);assert.deepEqual(browser.errors,[]);assert(browser.checks.filter(c=>c.engine==='webkit').every(c=>c.stageOverflow<=2));assert.equal(playback.native.length,12);assert(playback.native.every(x=>x.clips.length===6&&x.clips.every(c=>c.ended)));assert.equal(playback.decoded.length,2);assert(playback.decoded.every(x=>x.clips.length===audio.length));assert.deepEqual(playback.errors,[]);
 const layouts=json(folder+'final-layout/checks.json'),feedback=json(folder+'feedback-layout/checks.json'),preserved=json(folder+'preserved/checks.json'),worker=json(folder+'worker-preview-checks.json');assert.equal(layouts.checks.length,84);assert(layouts.checks.filter(c=>c.width>=390).every(c=>c.stageOverflow<=2));assert.equal(feedback.checks.length,16);assert(feedback.checks.every(c=>c.stageOverflow<=2));assert.equal(preserved.checks.length,8);assert(preserved.checks.every(c=>c.pixelIdentical));assert.equal(worker.checks.length,12);assert(worker.checks.every(c=>c.compiledPlayer&&c.fourCards&&c.correctFeedback&&c.resume));
 const checks=json(folder+'verification.json');for(const k of['types','lint','unit','build','allQuestions','allAnswerCards','allLanguageDimensions','allNewSpokenTexts','audioMetadata','losslessAudio','browserAndKeyboard','progressPreserved','currentAppearancePreserved','localOnly'])assert.equal(checks[k],true,k);
 const backup=json(folder+'backup.json');assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);assert.deepEqual(backup.evidenceFiles,r.evidenceFiles);assert(backup.parts.every(p=>p.verified&&p.fullReadback&&p.zipIntegrity&&p.driveId));return r;
}
export function readBeforeWordUseLanguageReview(file,r,read=readFileSync){return r.changedFiles.includes(file)?git('show',base+':'+file):read(file);}
